import { featured, weeklySpecial } from './products';

test('lists the featured products', () => {
  expect(featured().map(product => product.id)).toEqual(['mug', 'tote', 'lamp']);
});

test('offers the weekly special until it ends', () => {
  expect(weeklySpecial(new Date('2026-04-15'))?.id).toBe('rope');
  expect(weeklySpecial(new Date('2026-04-20'))).toBeUndefined();
});

